contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint _value) public payable {
        require(msg.sender == address(this));
        // Owner is this contract, so the deciding call should succeed iff the balance is enough.
        uint balanceBefore = address(c).balance;
        bool reverted;
        try c.withdraw(_value) {
            reverted = false;
        } catch {
            reverted = true;
        }
        assert(reverted == (_value > balanceBefore));
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint _value) public payable {
        // Precondition: caller must be the owner (this contract), since only the owner may call withdraw.
        require(msg.sender == address(this));
        // Record the balance before the deciding call.
        uint balanceBefore = address(c).balance;
        // Deciding call: owner attempts to withdraw _value wei.
        bool reverted;
        try c.withdraw(_value) {
            reverted = false;
        } catch {
            reverted = true;
        }
        // General rule: the withdrawal succeeds (does not revert) if and only if
        // the requested amount does not exceed the contract's balance.
        assert(reverted == (_value > balanceBefore));
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint _value) public payable {
        // Only the owner may call withdraw, and this contract is the owner after deployment.
        require(msg.sender == address(this));

        uint balanceBefore = address(c).balance;

        // Deciding call: owner attempts to withdraw _value wei.
        bool reverted;
        try c.withdraw(_value) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint balanceAfter = address(c).balance;

        // General rule: for the owner, withdraw(_value) succeeds exactly when
        // _value <= balanceBefore; and on success the contract's balance
        // decreases by exactly _value.
        assert(reverted == (_value > balanceBefore));
        assert(reverted || balanceBefore - balanceAfter == _value);
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint _value) public payable {
        uint balanceBefore = address(c).balance;
        bool reverted;
        try c.withdraw(_value) { reverted = false; } catch { reverted = true; }
        uint balanceAfter = address(c).balance;
        assert(reverted == (_value > balanceBefore) ? balanceAfter == balanceBefore : balanceBefore - balanceAfter == _value);
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    fallback() external payable {}
    receive() external payable {}

    function run(address target, uint value, bytes memory data) public payable {
        require(address(this).balance >= value, "not enough balance");
        require(target != address(0), "target zero");

        address ownerBefore = c.owner();
        uint depositsBefore = c.depositsCount();
        uint contractBalanceBefore = address(c).balance;
        uint targetBalanceBefore = target.balance;

        (bool callSucceeded, ) = target.call{value: 0}("");
        require(callSucceeded == true, "target must be callable");

        bool reverted;
        try c.sendMoney(target, value, data) {
            reverted = false;
        } catch {
            reverted = true;
        }

        address ownerAfter = c.owner();
        uint depositsAfter = c.depositsCount();
        uint contractBalanceAfter = address(c).balance;
        uint targetBalanceAfter = target.balance;

        bool valueTransferred = targetBalanceAfter == targetBalanceBefore + value;
        bool valueNotTransferred = targetBalanceAfter == targetBalanceBefore &&
                                   contractBalanceAfter == contractBalanceBefore;

        assert((reverted && valueNotTransferred && ownerAfter == ownerBefore && depositsAfter == depositsBefore) ||
               (!reverted && valueTransferred && ownerAfter == ownerBefore && depositsAfter == depositsBefore));
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    fallback() external payable {}
    receive() external payable {}

    function run(address target, uint value, bytes memory data) public payable {
        require(address(this).balance >= value, "not enough balance");
        require(target != address(0), "target zero");

        address ownerBefore = c.owner();
        uint depositsBefore = c.depositsCount();
        uint contractBalanceBefore = address(c).balance;
        uint targetBalanceBefore = target.balance;

        (bool probeOk, ) = target.call{value: value}("");
        require(probeOk, "target cannot accept value");

        bool reverted;
        try c.sendMoney(target, value, data) {
            reverted = false;
        } catch {
            reverted = true;
        }

        address ownerAfter = c.owner();
        uint depositsAfter = c.depositsCount();
        uint contractBalanceAfter = address(c).balance;
        uint targetBalanceAfter = target.balance;

        // Owner and depositsCount are never changed by sendMoney.
        assert(reverted == false &&
               ownerAfter == ownerBefore &&
               depositsAfter == depositsBefore &&
               contractBalanceAfter + value == contractBalanceBefore &&
               targetBalanceAfter == targetBalanceBefore + value);
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    receive() external payable {}
    fallback() external payable {}

    function run(address target, uint value, bytes memory data) public payable {
        require(address(this).balance >= value, "not enough balance");
        require(target != address(0), "target zero");

        // Give the target a way to accept Ether non-reverting for the deciding call.
        (bool setupOk, ) = target.call{value: 0}("");
        if (!setupOk) {
            // If target cannot even accept 0-value calls, it cannot accept value calls either.
            (bool probeOk, ) = target.call{value: value}(data);
            require(!probeOk, "target accepted value unexpectedly");
        }

        uint depositsBefore = c.depositsCount();
        uint contractBalanceBefore = address(c).balance;
        uint thisBalanceBefore = address(this).balance;
        uint targetBalanceBefore = target.balance;

        bool reverted;
        try c.sendMoney(target, value, data) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint depositsAfter = c.depositsCount();
        uint contractBalanceAfter = address(c).balance;
        uint thisBalanceAfter = address(this).balance;
        uint targetBalanceAfter = target.balance;

        // The only guaranteed effect of sendMoney: it succeeds iff the target can receive Ether with data,
        // it never changes depositsCount, and Ether only moves from c to target (or stays if target == c).
        if (target == address(c)) {
            assert(!reverted &&
                   depositsAfter == depositsBefore &&
                   contractBalanceAfter == contractBalanceBefore &&
                   thisBalanceAfter == thisBalanceBefore);
        } else {
            assert(depositsAfter == depositsBefore &&
                   contractBalanceAfter + value == contractBalanceBefore &&
                   thisBalanceAfter == thisBalanceBefore &&
                   ((!reverted && targetBalanceAfter == targetBalanceBefore + value) ||
                    (reverted && targetBalanceAfter == targetBalanceBefore)));
        }
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    receive() external payable {}
    fallback() external payable {}

    function run(address target, uint value, bytes memory data) public payable {
        require(address(this).balance >= value, "not enough balance");
        require(target != address(0), "target zero");

        uint depositsBefore = c.depositsCount();
        uint cBalBefore = address(c).balance;
        uint thisBalBefore = address(this).balance;
        uint targetBalBefore = target.balance;

        bool reverted;
        try c.sendMoney(target, value, data) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint depositsAfter = c.depositsCount();
        uint cBalAfter = address(c).balance;
        uint thisBalAfter = address(this).balance;
        uint targetBalAfter = target.balance;

        // The rule: only c -> target Ether move is possible; depositsCount never changes;
        // on revert nothing moves; on success c loses value and target gains value (unless target == c).
        assert(depositsAfter == depositsBefore &&
               thisBalAfter == thisBalBefore &&
               (
                   (reverted && cBalAfter == cBalBefore && targetBalAfter == targetBalBefore) ||
                   (!reverted && (
                       (target == address(c) && cBalAfter == cBalBefore) ||
                       (target != address(c) && cBalAfter + value == cBalBefore && targetBalAfter == targetBalBefore + value)
                   ))
               )
        );
    }
}

